.about-image .wp-block-cover__inner-container p {
    font-weight: 800;
    letter-spacing: 0.02em;
    text-shadow: 0 2px 12px rgba(0, 0, 0, 0.3);
    margin: 0;
    color: #ffffff;
}

/* Welcome Section */
.has-text-align-center.has-large-font-size {
    margin-top: 60px;
    margin-bottom: 20px;
    color: #1f2937;
    letter-spacing: 0.01em;
}

/* Section Headings */
.has-text-align-center[style*="font-size:28px"] {
    font-weight: 800;
    color: #111827;
    letter-spacing: 0.015em;
    margin-top: 40px;
    margin-bottom: 30px;
    position: relative;
    display: inline-block;
    width: 100%;
}

.has-text-align-center[style*="font-size:28px"]::after {
    content: '';
    display: block;
    width: 60px;
    height: 4px;
    background: #b50000;
    margin: 16px auto 0;
    border-radius: 2px;
}

/* Address Boxes - Modern Card Design */
.address-box {
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 20px;
    padding: 40px 30px;
    margin: 40px auto;
    max-width: 1200px;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05),
    0 2px 4px -1px rgba(0, 0, 0, 0.03);
    transition: all 0.3s ease;
}

.address-box:hover {
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.08),
    0 4px 6px -2px rgba(0, 0, 0, 0.04);
    transform: translateY(-2px);
}

.address-box .has-text-align-center {
    color: #374151;
    line-height: 1.8;
    font-size: 16px;
}

.address-box .has-text-align-center strong {
    color: #111827;
    font-weight: 700;
    font-size: 18px;
}

.address-box .has-text-align-center a {
    color: #b50000;
    text-decoration: none;
    transition: color 0.2s ease;
    font-weight: 500;
}

.address-box .has-text-align-center a:hover {
    color: #000000;
    text-decoration: underline;
}

/* Columns Layout in Address Box */
.address-box .wp-block-columns {
    margin-top: 30px;
    gap: 40px;
    align-items: center;
}

.address-box .wp-block-column {
    padding: 0;
}

/* Map Styling */
.address-box .wp-block-webfactory-map {
    border-radius: 16px;
    overflow: hidden;
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
    border: 2px solid #f3f4f6;
}

.address-box .wp-block-webfactory-map iframe {
    border-radius: 14px;
}

/* Opening Hours Styling */
.address-box .is-vertically-aligned-center p {
    background: #f9fafb;
    padding: 24px 28px;
    border-radius: 14px;
    border-left: 4px solid #b50000;
    font-size: 15px;
    line-height: 1.9;
    color: #1f2937;
}

.address-box .is-vertically-aligned-center p strong {
    color: #111827;
    font-weight: 700;
}

/* Spacer Adjustments */
.wp-block-spacer {
    margin: 0;
}

/* Responsive Design */
@media (max-width: 1024px) {
    .address-box {
        padding: 35px 25px;
        margin: 30px 20px;
    }

    .address-box .wp-block-columns {
        gap: 30px;
    }
}

@media (max-width: 782px) {
    .about-image .wp-block-cover__inner-container {
        padding: 60px 20px;
    }

    .about-image .wp-block-cover__inner-container p {
