    }

    .address-box {
        padding: 30px 20px;
        margin: 25px 15px;
        border-radius: 16px;
    }

    .address-box .wp-block-columns {
        flex-direction: column;
        gap: 25px;
    }

    .address-box .is-vertically-aligned-center p {
        padding: 20px 22px;
        font-size: 14px;
    }

    .has-text-align-center[style*="font-size:28px"] {
        font-size: 24px !important;
    }
}

@media (max-width: 600px) {
    .about-image.wp-block-cover {
        min-height: 400px !important;
    }

    .about-image .wp-block-cover__inner-container {
        padding: 40px 15px;
    }

    .about-image .wp-block-cover__inner-container p {
        font-size: 26px !important;
    }

    .address-box {
        padding: 25px 18px;
        margin: 20px 10px;
        border-radius: 14px;
    }

    .address-box .has-text-align-center {
        font-size: 15px;
    }

    .address-box .has-text-align-center strong {
        font-size: 17px;
    }

    .address-box .is-vertically-aligned-center p {
        padding: 18px 20px;
        font-size: 14px;
        line-height: 1.8;
    }

    .has-text-align-center[style*="font-size:28px"] {
        font-size: 22px !important;
    }

    .has-text-align-center[style*="font-size:28px"]::after {
        width: 50px;
        height: 3px;
        margin-top: 12px;
    }
}

/* Additional Polish */
.address-box .wp-block-spacer {
    display: block;
}

/* Smooth Animations */
.address-box,
.address-box a,
.address-box .wp-block-webfactory-map {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Focus States for Accessibility */
.address-box a:focus-visible {
    outline: 3px solid #b50000;
    outline-offset: 2px;
    border-radius: 4px;
}

/* ========================================
   PRODUCT VARIATIONS TABLE - RESPONSIVE DESIGN
   ======================================== */

/* Variations Table Base Styles */
table.variations {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    margin-bottom: 20px;
    border: none !important;
}

table.variations tbody {
    border: none !important;
}

table.variations tr {
    border: none !important;
    display: flex;
    flex-direction: column;
    margin-bottom: 25px;
    padding: 20px;
    background: transparent;
    border-radius: 12px;
    border: none !important;
}

/* Label Styling - Prevent Text Wrapping */
table.variations th.label {
    width: 100%;
    text-align: left;
    padding: 0 0 12px 0;
    border: none !important;
    font-weight: 700;
    font-size: 16px;
    color: #111827;
    white-space: nowrap;
    overflow: visible;
}

table.variations th.label label {
    display: inline-block;
    white-space: nowrap;
    font-family: 'DINPro', Arial, Helvetica, sans-serif;
}

h1.product_title.entry-title {
    margin-bottom: 2px;
}

.wp-singular .product .woocommerce-Price-amount.amount{
    font-size: 20px;
}

.body-col-1c .la-p-single-wrap .p-left.product-main-image {
    padding: 0 !important;
}

.wp-singular .product .product--large-image.woocommerce-product-gallery__image {
    margin-bottom: 0px;
}

.wp-singular .product .row {
    display: flex;
    justify-content: center;
    align-items: center;
}

.wp-singular .product .row .woocommerce-product-gallery__image img {
    scale: 1.1;
}

/* Value Cell */
table.variations td.value {
    width: 100%;
    padding: 0;
    border: none !important;
}

/* Swatch Control Container */
table.variations .swatch-control {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    align-items: center;
}

/* Auf der Einzel-Produktseite: gesamte Variationen-Tabelle scrollbar machen,
   damit die linke Bildspalte in ihrer Höhe stabil bleibt */
body.single-product table.variations {
    display: block; /* Basis: scrollbarer Block */
    max-height: min(420px, calc(100vh - 270px));
    overflow-y: auto;
    padding-right: 4px; /* etwas Platz für Scrollbar */
}

/* Auf größeren Screens: Variations-Zeilen dynamisch nebeneinander anordnen */
@media (min-width: 1024px) {
    body.single-product table.variations {
        display: flex;          /* macht die Zeilen zu flex-items */
        flex-wrap: wrap;
        gap: 18px;
    }
    body.single-product table.variations tr {
        width: calc(50% - 9px); /* zwei Spalten */
    }
}

/* Hide Default Select */
table.variations select {
    display: none;
}

/* Swatch Wrapper - Individual Items */
table.variations .swatch-wrapper {
    flex: 0 0 auto;
    margin: 0 !important;
    padding: 0;
    border: 2px solid #e5e7eb;
    border-radius: 10px;
    overflow: hidden;
    transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    background: white;
}

table.variations .swatch-wrapper:hover {
    border-color: #b50000;
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba(181, 0, 0, 0.15);
}

table.variations .swatch-wrapper.selected {
    border-color: #b50000;
    border-width: 3px;
    box-shadow: 0 0 0 3px rgba(181, 0, 0, 0.1);
}

/* Swatch Anchor - Override inline styles */
table.variations .swatch-wrapper a.swatch-anchor,
.swatch-control .swatch-wrapper a.swatch-anchor,
div[id^="picker_"] .swatch-wrapper a.swatch-anchor {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 80px !important;
    height: 80px !important;
    min-width: 80px !important;
    min-height: 80px !important;
    max-width: 80px !important;
    max-height: 80px !important;
    padding: 4px !important;
    text-decoration: none !important;
    position: relative !important;
}

table.variations .swatch-wrapper a.swatch-anchor:focus-visible {
    outline: 3px solid #b50000;
    outline-offset: 2px;
}

/* Swatch Images */
table.variations .swatch-wrapper img.swatch-img {
    width: 100% !important;
    height: 100% !important;
    object-fit: contain !important;
    display: block !important;
}

/* Swatch Label Text */
table.variations .swatch-wrapper .swatch-anchor-label {
    display: none;
    position: absolute;
    bottom: -30px;
    left: 50%;
    transform: translateX(-50%);
    background: #111827;
    color: white;
    padding: 6px 12px;
    border-radius: 6px;
    font-size: 12px;
    white-space: nowrap;
    z-index: 10;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.2s ease;
}

table.variations .swatch-wrapper:hover .swatch-anchor-label {
    display: block;
    opacity: 1;
}

/* Reset Link */
table.variations a.reset_variations {
    display: inline-block;
    margin-top: 12px;
    padding: 8px 16px;
    background: #f3f4f6;
    color: #374151;
    text-decoration: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    transition: all 0.2s ease;
    border: 1px solid #e5e7eb;
}

table.variations a.reset_variations:hover {
    background: #e5e7eb;
    color: #111827;
}

table.variations a.reset_variations:focus-visible {
    outline: 3px solid #b50000;
    outline-offset: 2px;
}

/* Disabled State */
table.variations .swatch-wrapper.disabled {
    opacity: 0.4;
    pointer-events: none;
    filter: grayscale(100%);
}

/* ========================================
   RESPONSIVE BREAKPOINTS
   ======================================== */

/* Tablet (max-width: 1024px) */
@media (max-width: 1024px) {
    table.variations tr {
        padding: 18px;
        margin-bottom: 20px;
    }

    table.variations th.label {
        font-size: 15px;
        padding-bottom: 10px;
    }

    table.variations .swatch-control {
        gap: 10px;
    }

    table.variations .swatch-wrapper a.swatch-anchor,
    .swatch-control .swatch-wrapper a.swatch-anchor,
    div[id^="picker_"] .swatch-wrapper a.swatch-anchor {
        width: 70px !important;
        height: 70px !important;
        min-width: 70px !important;
        min-height: 70px !important;
        max-width: 70px !important;
        max-height: 70px !important;
    }
}

/* Mobile (max-width: 768px) */
@media (max-width: 768px) {
    table.variations tr {
        padding: 16px;
        margin-bottom: 18px;
        border-radius: 10px;
    }

    table.variations th.label {
        font-size: 14px;
        padding-bottom: 10px;
    }

    table.variations .swatch-control {
        gap: 8px;
        justify-content: flex-start;
    }

    table.variations .swatch-wrapper a.swatch-anchor,
    .swatch-control .swatch-wrapper a.swatch-anchor,
    div[id^="picker_"] .swatch-wrapper a.swatch-anchor {
        width: 65px !important;
        height: 65px !important;
        min-width: 65px !important;
        min-height: 65px !important;
        max-width: 65px !important;
        max-height: 65px !important;
    }

    table.variations .swatch-wrapper {
        border-radius: 8px;
    }

    table.variations a.reset_variations {
        padding: 6px 14px;
        font-size: 13px;
    }
}

/* Small Mobile (max-width: 480px) */
@media (max-width: 480px) {
    table.variations tr {
        padding: 14px;
        margin-bottom: 16px;
    }

    table.variations th.label {
        font-size: 14px;
        padding-bottom: 8px;
    }

    table.variations .swatch-control {
        gap: 8px;
    }

    table.variations .swatch-wrapper a.swatch-anchor,
    .swatch-control .swatch-wrapper a.swatch-anchor,
    div[id^="picker_"] .swatch-wrapper a.swatch-anchor {
        width: 60px !important;
        height: 60px !important;
        min-width: 60px !important;
        min-height: 60px !important;
        max-width: 60px !important;
        max-height: 60px !important;
    }

    table.variations .swatch-wrapper {
        border-width: 2px;
    }

    table.variations .swatch-wrapper.selected {
        border-width: 2px;
    }

    table.variations a.reset_variations {
        width: 100%;
        text-align: center;
        margin-top: 10px;
    }
}

/* ========================================
   ATTRIBUTE PICKER LABEL (if used)
   ======================================== */

.attribute_pa_schaltung_picker_label,
.attribute_pa_farbe_picker_label {
    font-weight: 600;
    margin-bottom: 8px;
    color: #374151;
    font-size: 14px;
}

/* ========================================
   PRODUCT LOOP IMAGE SWATCHES
   ======================================== */

.bo-product-swatches {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 10px;
    flex-wrap: wrap;
}

/* Wrapper for each image swatch */
.bo-product-swatches .bo-swatch-wrapper {
    display: inline-block;
    flex-shrink: 0;
    width: 40px;
    height: 40px;
    border-radius: 4px;
    overflow: hidden;
    border: 2px solid #e5e7eb;
    transition: border-color 0.2s ease, transform 0.2s ease;
}

/* Product image inside swatch */
.bo-product-swatches .bo-swatch-wrapper .bo-swatch-img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
}

/* Hover effect */
.bo-product-swatches .bo-swatch-wrapper:hover {
    border-color: #9ca3af;
    transform: scale(1.08);
}

/* Active/selected state */
.bo-product-swatches .bo-swatch-wrapper.bo-swatch-active {
    border-color: #374151;
    transform: scale(1.08);
}

/* "+X" indicator for more variations */
.bo-swatch-more {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 600;
    color: #6b7280;
    min-width: 24px;
    height: 40px;
    padding: 0 4px;
}

/* Responsive adjustments */
@media (max-width: 768px) {
    .bo-product-swatches {
        gap: 5px;
        margin-top: 8px;
    }

    .bo-product-swatches .bo-swatch-wrapper {
        width: 32px;
        height: 32px;
    }

    .bo-swatch-more {
        font-size: 11px;
        min-width: 20px;
        height: 32px;
    }
}

