/* ===============================
   WooCommerce – Fixed price only
   Remove "ab" and crossed prices
   =============================== */

/* 1. Remove crossed-out (old) prices everywhere */
.woocommerce del,
.woocommerce del .woocommerce-Price-amount {
  display: none !important;
}

/* 2. Remove "ab" (price prefix) */
.woocommerce .price small,
.woocommerce .price .from,
.woocommerce .price .price-prefix {
  display: none !important;
}

/* 3. Safety: hide any theme-generated "ab" before price */
.woocommerce .price::before {
  content: none !important;
}

/* 4. Ensure final price looks clean */
.woocommerce .price,
.woocommerce .woocommerce-Price-amount {
  font-weight: 600;
  color: #111;
}
/* ===============================
   WooCommerce – Remove product meta
   SKU / Category / Brand
   =============================== */

/* Remove entire product meta block */
.woocommerce .product_meta {
  display: none;
}

/* Safety: hide individual rows in case theme outputs them separately */
.woocommerce .sku_wrapper,
.woocommerce .posted_in,
.woocommerce .tagged_as {
  display: none;
}
/* =====================================
   FORCE remove SKU / Category / Brand
   Cosy theme (text-based meta)
   ===================================== */

/* Hide any paragraph containing product meta labels */
.single-product .product--summary p:has(> strong),
.single-product .product--summary p:has(a[href*="/product-category/"]),
.single-product .product--summary p:has(a[href*="/marke/"]),
.single-product .product--summary p:has(a[href*="/brand/"]) {
  display: none !important;
}

/* Fallback: hide meta container if present */
.single-product .product--meta,
.single-product .product--summary .product-meta,
.single-product .product--summary .meta {
  display: none !important;
}

