inline:8.text:
/* --- Design tokens (scoped to .bo2 only) --- */
.bo2{--bo2-text:#1f2937;--bo2-muted:#6b7280;--bo2-link:#0ea5e9;--bo2-cta:#22c55e;--bo2-cta-text:#0b1220;--bo2-border:#e5e7eb;}
.bo2{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:var(--bo2-text)}
.bo2 a{color:inherit;text-decoration:none}
.bo2 a:hover{text-decoration:underline}
.bo2 a:focus-visible{outline:3px solid var(--bo2-link);outline-offset:2px;border-radius:.25rem}

.bo2-footer{max-width:1200px;margin:0 auto;padding:8px 8px 0}
.bo2-grid{display:grid;gap:40px;grid-template-columns:1.2fr 1.2fr 1fr 1fr;align-items:start}
@media (max-width:1024px){.bo2-grid{grid-template-columns:1fr 1fr}}
@media (max-width:640px){.bo2-grid{grid-template-columns:1fr}}

.bo2-title{font:700 2.1rem/1.15 ui-sans-serif,system-ui,Segoe UI,Roboto,Helvetica,Arial;margin:0 0 .75rem;letter-spacing:.01em}
.bo2-subtitle{font:700 2rem/1.15 ui-sans-serif,system-ui,Segoe UI,Roboto,Helvetica,Arial;margin:0 0 .75rem}
.bo2-list{list-style:none;margin:0;padding:0}
.bo2-list li{margin:.45rem 0}
.bo2-muted{color:var(--bo2-muted)}
.bo2-address{font-style:normal}

.bo2-locations{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:.75rem}
@media (max-width:640px){.bo2-locations{grid-template-columns:1fr}}
.bo2-location{font-size:.9rem}
.bo2-location h3{font:700 1.1rem/1.2 ui-sans-serif,system-ui,Segoe UI,Roboto,Helvetica,Arial;margin:0 0 .4rem;color:var(--bo2-text)}
.bo2-location p{margin:.3rem 0;line-height:1.5}

.bo2-brand{padding:12px 16px;border:1px solid var(--bo2-border);border-radius:16px;box-shadow:0 1px 0 rgba(0,0,0,.02)}
.bo2-logo{display:inline-flex;align-items:center;gap:.55rem;font:800 1.35rem/1.1 ui-sans-serif,system-ui,Segoe UI,Roboto,Helvetica,Arial;letter-spacing:.02em}
.bo2-logo-badge{display:inline-grid;place-items:center;width:34px;height:34px;border-radius:9px;background:#111;color:#fff;font-weight:800;font-size:.9rem;line-height:1}
.bo2-tagline{margin:.35rem 0 1rem;color:var(--bo2-muted)}
.bo2-cta{display:inline-block;padding:12px 18px;border-radius:999px;font-weight:800;background:var(--bo2-cta);color:var(--bo2-cta-text);text-decoration:none;box-shadow:0 1px 0 rgba(0,0,0,.06)}

