.catalog-grid-1 .product-category .woocommerce-loop-category__title {
  text-align: center;
  margin: 0;
  color: #fff;
  position: absolute;
  transition: all 450ms ease-out;
  width: 90%;
  left: 5%;
  z-index: 9;
  bottom: 50%;
  opacity: 0;
  visibility: hidden;
  transform: translate(0, 50%) scale(2);
  -ms-transform: translate(0, 50%) scale(2);
  -webkit-transform: translate(0, 50%) scale(2);
