.mega-menu .mm-popup-wide .inner > ul.sub-menu > li > a {
  padding: 8px 15px;
  display: inline-block;
  background-color: transparent;
  text-transform: uppercase;
  font-weight: bold;
  font-size: 16px;
}

.menu--horizontal .mm-item-level-0.mm-item-has-sub > a > .mm-text:after {
